import * as THREE from 'three';
export function createProjectionCanvasView({root=document,onHover=()=>{},onLeave=()=>{}}){
 const $=s=>root.querySelector(s);
 let projection={data:null,mode:'counts',targets:new Set()},RESPONSE={};
 const TARGETS={elevator:{label:'电梯井',color:'#c187ff'},spillway:{label:'溢流泄洪',color:'#2ecfff'},platform:{label:'加宽平台',color:'#ffad58'},water:{label:'水体边界',color:'#3aa9ff'},dam:{label:'坝体边界',color:'#f4e8bf'},gallery:{label:'廊道',color:'#48e39a'}};
 function heatColor(t){const stops=[[.0,0x397cff],[.38,0x24d5c1],[.72,0xffd166],[1,0xff5f55]],out=new THREE.Color(stops[0][1]);for(let i=0;i<stops.length-1;i++){const [a,ca]=stops[i],[b,cb]=stops[i+1];if(t>=a&&t<=b)return out.set(ca).lerp(new THREE.Color(cb),(t-a)/(b-a))}return out.set(stops.at(-1)[1])}
 function colorCss(t){const c=heatColor(THREE.MathUtils.clamp(t,0,1));return`rgb(${Math.round(c.r*255)},${Math.round(c.g*255)},${Math.round(c.b*255)})`}
 function selectedSignificance(q){let v=0;for(const id of projection.targets)v=Math.max(v,q.sigByTarget[id]||0);return v}
 function drawTargetContour(ctx,d,id,w,h){const n=d.n,at=(x,y)=>x>=0&&x<n&&y>=0&&y<n?d.values[y*n+x].q:null,inside=(x,y)=>!!at(x,y)?.targetMask[id],depth=q=>id==='dam'?q.edgeProfile.firstConcrete:q.edgeProfile.targetEntry[id],length=q=>id==='dam'?q.totals.concrete:q.targetLengths[id],threshold=id==='dam'?[4,5]:id==='water'?[2,2]:[1.5,.75],feature=(a,b)=>a&&b&&a.targetMask[id]&&b.targetMask[id]&&((Number.isFinite(depth(a))&&Number.isFinite(depth(b))&&Math.abs(depth(a)-depth(b))>=threshold[0])||Math.abs(length(a)-length(b))>=threshold[1]);ctx.save();ctx.strokeStyle=TARGETS[id].color;ctx.lineJoin='round';ctx.lineCap='round';ctx.shadowColor='rgba(0,0,0,.9)';ctx.shadowBlur=2.5;ctx.beginPath();for(let y=0;y<n;y++)for(let x=0;x<n;x++){if(!inside(x,y))continue;const l=x*w,r=(x+1)*w,t=ctx.canvas.height-(y+1)*h,b=ctx.canvas.height-y*h;if(!inside(x-1,y)){ctx.moveTo(l,t);ctx.lineTo(l,b)}if(!inside(x+1,y)){ctx.moveTo(r,t);ctx.lineTo(r,b)}if(!inside(x,y+1)){ctx.moveTo(l,t);ctx.lineTo(r,t)}if(!inside(x,y-1)){ctx.moveTo(l,b);ctx.lineTo(r,b)}}ctx.lineWidth=2.25;ctx.globalAlpha=1;ctx.stroke();ctx.beginPath();for(let y=0;y<n;y++)for(let x=0;x<n;x++){const q=at(x,y),l=x*w,r=(x+1)*w,t=ctx.canvas.height-(y+1)*h,b=ctx.canvas.height-y*h;if(feature(q,at(x+1,y))){ctx.moveTo(r,t);ctx.lineTo(r,b)}if(feature(q,at(x,y+1))){ctx.moveTo(l,t);ctx.lineTo(r,t)}}ctx.lineWidth=1.1;ctx.globalAlpha=.82;ctx.shadowBlur=1.5;ctx.stroke();ctx.restore()}
 function drawProjection(){const d=projection.data;if(!d)return;const canvas=$('#projectionCanvas'),ctx=canvas.getContext('2d'),n=d.n,w=canvas.width/n,h=canvas.height/n,mode=projection.mode;ctx.clearRect(0,0,canvas.width,canvas.height);for(let iy=0;iy<n;iy++)for(let ix=0;ix<n;ix++){const q=d.values[iy*n+ix],v=mode==='counts'?q.displayCount:mode==='transmission'?q.displayTransmission:selectedSignificance(q),t=mode==='counts'?THREE.MathUtils.clamp((Math.log10(Math.max(.1,v))+1)/6,0,1):mode==='transmission'?THREE.MathUtils.clamp((Math.log10(Math.max(1e-6,v))+6)/6,0,1):THREE.MathUtils.clamp(v/5,0,1);ctx.fillStyle=mode==='significance'&&!projection.targets.size?'#10202a':colorCss(t);ctx.fillRect(ix*w,canvas.height-(iy+1)*h,w+.5,h+.5)}for(const id of projection.targets)drawTargetContour(ctx,d,id,w,h);const selected=[...projection.targets],pixels=selected.length?d.values.filter(q=>selected.some(id=>q.q.targetMask[id])).length:0,roi=Math.sqrt(d.values.reduce((s,q)=>s+selectedSignificance(q)**2,0)),title=mode==='counts'?`${RESPONSE.exposureDays}天预计计数`:mode==='transmission'?'坝体透射率':'结构对比显著度';$('#projectionReadout').innerHTML=`${title} · 总计数 ${Math.round(d.total).toLocaleString()}<br>加权透射 ${(d.weightedTransmission*100).toFixed(2)}%${selected.length?` · 选中ROI ${roi.toFixed(1)}σ<br>${pixels} 个结构像素 · ${selected.map(id=>TARGETS[id].label).join('、')}`:'<br>结构标识图层未加载'}`}
 function hover(ev){const d=projection.data;if(!d)return;const r=ev.currentTarget.getBoundingClientRect(),ix=Math.max(0,Math.min(d.n-1,Math.floor((ev.clientX-r.left)/r.width*d.n))),iy=Math.max(0,Math.min(d.n-1,d.n-1-Math.floor((ev.clientY-r.top)/r.height*d.n))),q=d.values[iy*d.n+ix];onHover(d,ix,iy);$('#projectionReadout').innerHTML=`像素 (${ix+1},${iy+1}) · sx ${q.sx.toFixed(2)} · sy ${q.sy.toFixed(2)}<br>${Math.round(q.count)} 事件/${RESPONSE.exposureDays}天 · 透射 ${(q.transmission*100).toFixed(3)}%<br>柱密度 ${q.q.mwe.toFixed(0)} m.w.e.`;}
 const canvas=$('#projectionCanvas'),leave=()=>{onLeave();drawProjection();};canvas.addEventListener('mousemove',hover);canvas.addEventListener('mouseleave',leave);
 return Object.freeze({draw(state,response){projection=state;RESPONSE={...response};drawProjection();},dispose(){canvas.removeEventListener('mousemove',hover);canvas.removeEventListener('mouseleave',leave);}});
}
